// SCRAPER: EuroCham
// Output: standardized 7-field schema for downstream pipeline
// Normalize Job Data -> Dedupe -> Groq AI -> Google Sheets
// ============================================================

const html = $input.first()?.json?.data || "";

function sanitize(text) {
  if (!text) return "";
  let t = String(text);

  t = t.replace(/<[^>]*>?/g, " ");

  const entities = {
    "&nbsp;": " ", "&amp;": "&", "&lt;": "<", "&gt;": ">",
    "&quot;": '"', "&#39;": "'", "&apos;": "'", "&#038;": "&",
    "&#8211;": "-", "&#8212;": "-", "&rsquo;": "'", "&lsquo;": "'",
    "&rdquo;": '"', "&ldquo;": '"', "&ndash;": "-", "&mdash;": "-"
  };
  t = t.replace(/&nbsp;|&amp;|&lt;|&gt;|&quot;|&#39;|&apos;|&#038;|&#8211;|&#8212;|&rsquo;|&lsquo;|&rdquo;|&ldquo;|&ndash;|&mdash;/g, m => entities[m]);
  t = t.replace(/&#(\d+);/g, (_, dec) => String.fromCharCode(dec));
  t = t.replace(/[*_#`\[\]]/g, "");
  t = t.replace(/\s+/g, " ").trim();

  return t;
}

function extractId(url) {
  if (!url) return "";
  const match = String(url).match(/(\d+)/);
  return match ? match[1] : "";
}

let results = [];
const blocks = html.match(/<div class="elementor-posts-container[^>]*>([\s\S]*?)<\/article>/g) || [html];

for (let block of blocks) {
  let innerMatch;
  const itemRegex = /<h4 class="elementor-heading-title[^>]*>\s*<a href="([^"]+)">([\s\S]*?)<\/a>([\s\S]*?)(?=<h4|$)/g;

  while ((innerMatch = itemRegex.exec(block)) !== null) {
    const url = innerMatch[1];
    const fullTitleText = sanitize(innerMatch[2]);
    const descriptiveText = sanitize(innerMatch[3]);

    let jobTitle = fullTitleText;
    let organisation = "N/A";
    let location = "Cambodia";

    const dashSeparators = [" – ", " — ", " - "];
    for (let separator of dashSeparators) {
      if (fullTitleText.includes(separator)) {
        let parts = fullTitleText.split(separator);
        jobTitle = parts[0].trim();
        organisation = parts[1].trim();
        break;
      }
    }

    if (descriptiveText.includes("Company.")) {
      const compMatch = descriptiveText.match(/Company\.\s*([^.]+)/i);
      if (compMatch) organisation = compMatch[1].trim();
    }

    if (descriptiveText.includes("Location.")) {
      const locMatch = descriptiveText.match(/Location\.\s*([^.]+)/i);
      if (locMatch && locMatch[1].trim().length > 3) {
        location = locMatch[1].trim();
      }
    }

    jobTitle = sanitize(jobTitle);
    organisation = sanitize(organisation) || "N/A";
    location = sanitize(location) || "Cambodia";

    if (!jobTitle) continue;

    results.push({
      json: {
        source: "EuroCham",
        id: extractId(url),
        title: jobTitle,
        organisation: organisation,
        location: location,
        link: url || "",
        description: descriptiveText,
        // Downstream normalization keys
        raw_title: jobTitle,
        raw_company: organisation,
        raw_location: location,
        raw_description: descriptiveText,
        source_url: url
      }
    });
  }
}

// Safety cap to top 15 newest items per run
return results.slice(0, 15);

