const html = $input.first()?.json?.data || "";
const blockRegex = /<div class="tgme_widget_message_wrap[^>]*>([\s\S]*?)<\/div>\s*<\/div>\s*<\/div>/g;

function sanitize(text) {
  if (!text) return "";
  let t = String(text);

  t = t.replace(/<[^>]*>?/g, " ");

  const entities = {
    "&nbsp;": " ", "&amp;": "&", "&lt;": "<", "&gt;": ">",
    "&quot;": '"', "&#39;": "'", "&apos;": "'", "&#33;": "!",
    "&rsquo;": "'", "&lsquo;": "'", "&rdquo;": '"', "&ldquo;": '"',
    "&ndash;": "-", "&mdash;": "-"
  };
  t = t.replace(/&nbsp;|&amp;|&lt;|&gt;|&quot;|&#39;|&apos;|&#33;|&rsquo;|&lsquo;|&rdquo;|&ldquo;|&ndash;|&mdash;/g, m => entities[m]);
  t = t.replace(/&#(\d+);/g, (_, dec) => String.fromCharCode(dec));
  t = t.replace(/[*_#`]/g, "");
  t = t.replace(/\s+/g, " ").trim();

  return t;
}

function stripEmoji(text) {
  return String(text || "")
    .replace(/[\uE000-\uF8FF]|\uD83C[\uDC00-\uDFFF]|\uD83D[\uDC00-\uDFFF]|[\u2011-\u26FF]|\uD83E[\uDD00-\uDFFF]/g, "")
    .trim();
}

function extractId(url) {
  if (!url) return "";
  const match = String(url).match(/(\d+)/);
  return match ? match[1] : "";
}

let match;
let results = [];

while ((match = blockRegex.exec(html)) !== null) {
  const blockHtml = match[1];
  const textMatch = blockHtml.match(/<div class="tgme_widget_message_text[^>]*>([\s\S]*?)<\/div>/);
  if (!textMatch) continue;

  let rawText = textMatch[1]
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/?[^>]+(>|$)/g, "")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#33;/g, "!")
    .replace(/&#39;/g, "'")
    .trim();

  if (rawText.length < 20 || rawText.toLowerCase().includes("welcome to")) continue;

  const lowerText = rawText.toLowerCase();
  const jobHallmarks = [
    "position", "requirement", "deadline", "closing date", "salary", "apply",
    "cv", "ជ្រើសរើស", "ត្រូវការ", "តួនាទី", "ប្រាក់ខែ", "លក្ខខណ្ឌ"
  ];
  let score = 0;
  for (let hallmark of jobHallmarks) {
    if (lowerText.includes(hallmark)) score++;
  }
  if (score < 1) continue;

  let lines = rawText.split('\n').map(l => l.trim()).filter(l => l.length > 0);
  let title = stripEmoji(lines[0] || "");

  let organisation = "N/A";
  const orgMatchEnglish = rawText.match(/(?:opportunity from|hiring from)\s+([^\n,.:]+)/i) ||
                          rawText.match(/([^\n,.:]+(?:co\.,\s*ltd|plc|group|trading|solutions|capital|finance))/i);
  const orgMatchKhmer = rawText.match(/ក្រុមហ៊ុន\s+([^\n\s៖]+[^\n៖]*)/);

  if (orgMatchEnglish) {
    organisation = orgMatchEnglish[1].trim();
  } else if (orgMatchKhmer) {
    organisation = orgMatchKhmer[1].trim();
  } else if (title.includes("ត្រូវការ") || title.includes("ជ្រើសរើស")) {
    let splitTitle = title.split(/(?:ត្រូវការ|ជ្រើសរើស)/);
    if (splitTitle[0].trim().length > 2) organisation = splitTitle[0].trim();
  }

  organisation = stripEmoji(organisation).replace(/^[:\s-]+|[:\s-]+$/g, '').trim();
  if (!organisation) organisation = "N/A";

  const location = "Cambodia";
  const linkMatch = blockHtml.match(/href="([^"]+?camhrjobs\/\d+)"/);
  const url = linkMatch ? linkMatch[1] : "https://t.me/s/camhrjobs";

  results.push({
    json: {
      source: "CamHR",
      id: extractId(url),
      title: sanitize(title),
      organisation: sanitize(organisation) || "N/A",
      location: location,
      link: url,
      description: sanitize(rawText),
      // Downstream normalization keys
      raw_title: sanitize(title),
      raw_company: sanitize(organisation) || "N/A",
      raw_location: location,
      raw_description: sanitize(rawText),
      source_url: url
    }
  });
}

// Safety cap to top 15 newest items per run
return results.slice(0, 15);

