function formatToPhnomPenh(isoString) {
  if (!isoString) return null;
  const date = new Date(isoString);
  if (isNaN(date.getTime())) return null;
  const phnomPenhTime = new Date(date.getTime() + 7 * 60 * 60 * 1000);
  return phnomPenhTime.toISOString().replace('Z', '+07:00');
}

function isJobActive(fetchedAt, closingDate) {
  const now = new Date();
  if (closingDate) {
    const closing = new Date(closingDate);
    if (!isNaN(closing.getTime())) {
      return closing >= now;
    }
  }
  if (fetchedAt) {
    const fetched = new Date(fetchedAt);
    if (!isNaN(fetched.getTime())) {
      const daysSinceFetched = (now - fetched) / (1000 * 60 * 60 * 24);
      return daysSinceFetched <= 90;
    }
  }
  return true;
}

