const now = Date.now();
const MAX_AGE_MS = 90 * 24 * 60 * 60 * 1000;
const CAMBODIA_OFFSET = '+07:00';

function parseSheetDate(value, closingDate = false) {
  if (value === null || value === undefined || value === '') return null;

  // Google Sheets may provide a serial date number.
  if (typeof value === 'number' && value > 20000 && value < 80000) {
    const timestamp = Date.UTC(1899, 11, 30) + value * 24 * 60 * 60 * 1000;
    return Number.isFinite(timestamp) ? timestamp : null;
  }

  let text = String(value).trim();
  if (!text) return null;

  // Treat date-only values as Cambodian calendar dates. Keep closing dates
  // active until the end of the stated day.
  const isoDate = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:T00:00(?::00(?:\.000)?)?(?:Z|[+-]\d{2}:?\d{2})?)?$/);
  if (isoDate) {
    const [, year, month, day] = isoDate;
    const time = closingDate ? 'T23:59:59.999' : 'T00:00:00.000';
    const timestamp = Date.parse(`${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}${time}${CAMBODIA_OFFSET}`);
    return Number.isFinite(timestamp) ? timestamp : null;
  }

  // Also accept day-first numeric dates commonly used in Cambodia (D/M/YYYY).
  const numericDate = text.match(/^(\d{1,2})[/.\-](\d{1,2})[/.\-](\d{4})$/);
  if (numericDate) {
    const [, day, month, year] = numericDate;
    const time = closingDate ? 'T23:59:59.999' : 'T00:00:00.000';
    const timestamp = Date.parse(`${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}${time}${CAMBODIA_OFFSET}`);
    return Number.isFinite(timestamp) ? timestamp : null;
  }

  // Remove ordinal suffixes so values such as "11th November 2026" parse.
  text = text.replace(/\b(\d{1,2})(st|nd|rd|th)\b/gi, '$1');
  const parsed = Date.parse(text);
  return Number.isFinite(parsed) ? parsed : null;
}

function isActiveForFeed(row) {
  const closeTimestamp = parseSheetDate(row['Closing Date'], true);
  if (closeTimestamp !== null) return closeTimestamp >= now;

  // Date Fetched is only written for new rows by this workflow, so it acts as
  // the immutable first-seen date when the publisher gives no closing date.
  const firstSeenTimestamp = parseSheetDate(row['Date Fetched']);
  if (firstSeenTimestamp === null) return true; // Keep rows whose age is unknown.
  return now - firstSeenTimestamp <= MAX_AGE_MS;
}

